'use client';

import { PaymentButton } from './PaymentButton';

interface Plan {
  id: string;
  name: string;
  price: number;
  priceId: string;
  interval: 'month' | 'year';
  features: string[];
  highlighted?: boolean;
  metadata?: Record<string, string>;
}

interface PricingTableProps {
  plans: Plan[];
  customerEmail?: string;
  successUrl?: string;
  cancelUrl?: string;
}

export function PricingTable({
  plans,
  customerEmail,
  successUrl,
  cancelUrl,
}: PricingTableProps) {
